function BtnProcessOverViewNode:OnEnable()
    self:SetProcessPopUpStatus(false)
    local isProcessUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3014)
    local state = isProcessUnLock and 1 or 2
    CfUtils.SetUISwitchImage(self.BtnIcon,state)
    CfUtils.SetActive(self.Animation.gameObject,isProcessUnLock)
    --self:RefreshGridView()
    self:RefreshAni()
    self:StartUpdate()
end

function BtnProcessOverViewNode:StartUpdate()
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function()
            self:Update()
        end
        self._behaviourAction = behaviourAction
    end
end

function BtnProcessOverViewNode:Update()
    if Utils.TouchCount() > 0 and (not self.__closing) then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self._cacheRectTrans, position,
                    UIModule.RootCanvas.canvas.worldCamera)
            if not isInRect then
                ---不在区域中
                if self.ProcessOverviewPopUp.gameObject.activeSelf then
                    self:OnBtnProcessClick()
                end
            end
        end
    end
end

function BtnProcessOverViewNode:OnDisable()
    if self._behaviourAction then
        self._behaviourAction.UpdateAction = nil
        self._behaviourAction = nil
    end
end

function BtnProcessOverViewNode:AddUIClick()
    SetButtonAction(self.BtnProcessOverview,Bind(self,self.OnBtnProcessClick))
end

