function BtnProcessOverViewNode:RefreshAni()
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local isProcessUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3014)
    local isInProcess = playerComp:IsInProcess()
    local aniName = isInProcess and "UIHomeView_BtnProcess_Activate" or "UIHomeView_BtnProcess_Idle"
    CfUtils.PlayAnimation(self.Animation,aniName)
    local redGo = GameUtils.GetRedPointGo(self.BtnProcessOverview.gameObject)
    if redGo then
        if isProcessUnLock then
            local isHaveRedPoint = playerComp:IsHaveRedPoint()
            KTool.SetActive(redGo,isHaveRedPoint)
        else
            KTool.SetActive(redGo,false)
        end
    end
end

function BtnProcessOverViewNode:SetProcessPopUpStatus(status)
    CfUtils.SetActive(self.ProcessOverviewPopUp.gameObject,status)
end

function BtnProcessOverViewNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:RemovePlayCo()
    self:Delete()
end

function BtnProcessOverViewNode:OnBtnProcessClick()
    if self.isPlay then return end
    self:RemovePlayCo()
    self.isPlay = true
    if not self.ProcessOverviewPopUp.gameObject.activeSelf then
        GameUtils.Request(Interfaces.MainViewProcessRewards,{},function(request,response)
            if response.errCode == 0 then
                local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                playerComp:UpdateProgressInfo(response.data.mainViewProcessInfo)
                self.responseData =  playerComp:UpdateProgressRewardInfo(response.data.mainViewProcessRewards)
                Events.Broadcast(Constants.EventNames.HideGroupState,false)
                self:SetProcessPopUpStatus(true)
                self:RefreshGridView()
                self.isPlay = false
            end
        end)
    else
        self.playCo = cs_coroutine.start(function()
            CfUtils.ListViewEachItem(self.LoopList,CellPath,function(env,index,totalIndex)
                env:PlayAniEnd("UIHomeView_ProcesOverViewPopUp_Cell_Contract",totalIndex - index + 1)
                return false
            end)
            cs_coroutine.yield_return(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.06 * self.LoopList.ShownItemCount))
            self:SetProcessPopUpStatus(false)
            Events.Broadcast(Constants.EventNames.HideGroupState,true)
            self.isPlay = false
        end)
    end
end

function BtnProcessOverViewNode:RemovePlayCo()
    if not isNull(self.playCo) then
        cs_coroutine.stop(self.playCo)
        self.playCo = nil
    end
end

function BtnProcessOverViewNode:RefreshGridView()
    self.allVos = CfUtils.GetCf(AutoIds.IdSetting6055, "CommonModuleTipsVo", true)
    table.sort(self.allVos,function(a,b) return a.sort < b.sort  end)
    if self.LoopList then
        if not self.LoopList.IsListViewInit then
            self.LoopList:InitListView(#self.allVos, Bind(self, self.OnRefreshCellIndex))
        else
            GameUtils.ReloadData(self.LoopList, #self.allVos)
        end
    end
end

function BtnProcessOverViewNode:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= table.count(self.allVos) then
        return
    end
    local data = self.allVos[index + 1]
    local cell = listView:NewListViewItem(CellName)
    local cellEnv = CfUtils.GetLuaScr(cell, CellPath)
    if cellEnv then
        local isHaveReward = self.responseData[data.id] == 1 and true or false
        cellEnv:RefreshUI(data,isHaveReward)
        cellEnv:SetCallBack(function()
            self:RefreshAni()
        end,function() self:OnBtnProcessClick()  end)

        cellEnv:PlayAni("UIHomeView_ProcesOverViewPopUp_Cell_Expand",index)
    end
    return cell
end

return BtnProcessOverViewNode